import csv
import json
import os

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"
SOL_PATH = os.path.join(SUB_DIR, "solution.csv")

def main():
    os.makedirs(SUB_DIR, exist_ok=True)

    # ---------- Load data ----------
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        config = json.load(f)
    gap = float(config.get("solver_mip_gap", 0.0005))
    feas_tol = float(config.get("feasibility_tolerance", 1e-5))

    days = []
    with open(os.path.join(DATA_DIR, "days.csv")) as f:
        for row in csv.DictReader(f):
            days.append(row["day"])

    channels = {}
    with open(os.path.join(DATA_DIR, "channels.csv")) as f:
        for row in csv.DictReader(f):
            channels[row["channel_id"]] = {
                "cap": float(row["daily_impression_capacity"]),
                "tier": int(row["brand_safety_tier"]),
            }

    campaigns = {}
    with open(os.path.join(DATA_DIR, "campaigns.csv")) as f:
        for row in csv.DictReader(f):
            campaigns[row["campaign_id"]] = {
                "budget": float(row["budget"]),
                "min": float(row["min_impressions"]),
                "max": float(row["max_impressions"]),
                "tier": int(row["required_brand_safety_tier"]),
            }

    eligible = {}  # (c,k) -> dict
    with open(os.path.join(DATA_DIR, "campaign_channel_eligibility.csv")) as f:
        for row in csv.DictReader(f):
            c, k = row["campaign_id"], row["channel_id"]
            if c not in campaigns or k not in channels:
                continue
            if channels[k]["tier"] < campaigns[c]["tier"]:
                continue  # brand-safety rule
            eligible[(c, k)] = {
                "cost": float(row["cpm_cost"]),
                "val": float(row["expected_value_per_thousand"]),
                "share": float(row["max_share"]),
            }

    # ---------- Build LP ----------
    model = Model("retail_media")
    model.setParam("gaprel", gap)

    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    x = {}
    obj_coeff = {}
    for (c, k), d in eligible.items():
        coef = (d["val"] - d["cost"]) / 1000.0
        obj_coeff[(c, k)] = coef
        for t in days:
            x[(c, k, t)] = model.addVar(
                name=f"x_{c}_{k}_{t}", vtype="C", lb=0.0, ub=campaigns[c]["max"], obj=0.0
            )

    obj_expr = quicksum([obj_coeff[(c, k)] * x[(c, k, t)] for (c, k) in eligible for t in days])
    model.setObjective(obj_expr, sense="maximize")

    # Channel daily capacity
    for k in channels:
        cap = channels[k]["cap"]
        for t in days:
            terms = [x[(c, k, t)] for (c, kk) in eligible if kk == k]
            if terms:
                model.addCons(quicksum(terms) <= cap, name=f"cap_{k}_{t}")

    # Campaign min / max / budget / share
    for c, cd in campaigns.items():
        ck_pairs = [(c, k) for (c2, k) in eligible if c2 == c]
        if not ck_pairs:
            continue
        total_terms = [x[(c, k, t)] for (c, k) in ck_pairs for t in days]
        model.addCons(quicksum(total_terms) >= cd["min"], name=f"min_{c}")
        model.addCons(quicksum(total_terms) <= cd["max"], name=f"max_{c}")
        model.addCons(
            quicksum([eligible[(c, k)]["cost"] / 1000.0 * x[(c, k, t)] for (c, k) in ck_pairs for t in days])
            <= cd["budget"],
            name=f"budget_{c}",
        )
        for (c, k) in ck_pairs:
            s = eligible[(c, k)]["share"]
            lhs = quicksum([x[(c, k, t)] for t in days]) - s * quicksum(total_terms)
            model.addCons(lhs <= 0.0, name=f"share_{c}_{k}")

    # ---------- Solve ----------
    status = None
    try:
        model.optimize()
        status = model.getStatus()
        print("Solver status:", status)
        if model.getNSols() > 0:
            print("Objective:", model.getObjVal())
    except Exception as e:
        print("Solver error:", e)
        status = "error"

    # ---------- Extract & validate ----------
    rows = []
    if status in ("optimal", "bestsollimit", "timelimit", "gap"):
        sol = model.getBestSol()
        if sol is not None:
            for (c, k, t), var in x.items():
                v = model.getVal(var)
                if v > 1e-6:
                    rows.append((c, k, t, round(v, 8)))

            # Validation
            camp_tot = {}
            camp_cost = {}
            chan_day = {}
            for c, k, t, v in rows:
                camp_tot[(c, k)] = camp_tot.get((c, k), 0.0) + v
                camp_tot[c] = camp_tot.get(c, 0.0) + v
                camp_cost[c] = camp_cost.get(c, 0.0) + eligible[(c, k)]["cost"] / 1000.0 * v
                chan_day[(k, t)] = chan_day.get((k, t), 0.0) + v

            ok = True
            for c, cd in campaigns.items():
                tot = camp_tot.get(c, 0.0)
                if tot < cd["min"] - 1e-4:
                    ok = False
                    print(f"VIOLATION min {c}: {tot} < {cd['min']}")
                if tot > cd["max"] + 1e-4:
                    ok = False
                    print(f"VIOLATION max {c}: {tot} > {cd['max']}")
                if camp_cost.get(c, 0.0) > cd["budget"] + 1e-4:
                    ok = False
                    print(f"VIOLATION budget {c}: {camp_cost.get(c,0.0)} > {cd['budget']}")
            for k, t in chan_day:
                if chan_day[(k, t)] > channels[k]["cap"] + 1e-4:
                    ok = False
                    print(f"VIOLATION capacity {k} {t}: {chan_day[(k,t)]} > {channels[k]['cap']}")
            for key, v in camp_tot.items():
                if not isinstance(key, tuple):
                    continue  # campaign-level totals stored under plain campaign id
                c, k = key
                s = eligible[(c, k)]["share"]
                if v > s * camp_tot[c] + 1e-4:
                    ok = False
                    print(f"VIOLATION share {c} {k}: {v} > {s}*{camp_tot[c]}")
            print("Validation:", "PASS" if ok else "FAIL")
        else:
            print("No solution found.")

    # ---------- Write solution ----------
    with open(SOL_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["campaign_id", "channel_id", "day", "impressions"])
        for c, k, t, v in rows:
            w.writerow([c, k, t, f"{v:.8f}"])
    print("Wrote", SOL_PATH, "rows:", len(rows))

    model.free()

if __name__ == "__main__":
    main()
